"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[8590],{7805(e,n,t){t.r(n),t.d(n,{assets:()=>d,contentTitle:()=>c,default:()=>m,frontMatter:()=>l,metadata:()=>s,toc:()=>p});const s=JSON.parse('{"id":"part3-agent-protocols/mcp-fundamentals","title":"MCP Fundamentals with a Simple Database Example","description":"MCP (Model Context Protocol) is a standard way for an \\"AI host\\" (an app that uses an LLM) to connect to external capabilities through MCP servers.","source":"@site/docs/part3-agent-protocols/01-mcp-fundamentals.mdx","sourceDirName":"part3-agent-protocols","slug":"/part3-agent-protocols/01-mcp-fundamentals","permalink":"/tutorials/part3-agent-protocols/01-mcp-fundamentals","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":1,"frontMatter":{"title":"MCP Fundamentals with a Simple Database Example","slug":"/part3-agent-protocols/01-mcp-fundamentals","description":"MCP (Model Context Protocol) is a standard way for an \\"AI host\\" (an app that uses an LLM) to connect to external capabilities through MCP servers.","sidebar_label":"1. MCP fundamentals","pagination_label":"1. MCP fundamentals","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"Part overview","permalink":"/tutorials/part3-agent-protocols/overview"},"next":{"title":"2. MCP discovery, remote transport, and auth","permalink":"/tutorials/part3-agent-protocols/02-mcp-discovery-remote-auth"}}');var o=t(4848),r=t(8453),i=t(8172);const a=JSON.parse('{"sourcePath":"part3-agent-protocols/01-mcp-fundamentals.html","route":"/part3-agent-protocols/01-mcp-fundamentals","kind":"chapter","partId":"part3","partLabel":"Part III - Agent Protocols & Integration","accent":"violet","heading":"MCP Fundamentals with a Simple Database Example","title":"MCP Fundamentals with a Simple Database Example","description":"MCP (Model Context Protocol) is a standard way for an \\"AI host\\" (an app that uses an LLM) to connect to external capabilities through MCP servers.","readingMinutes":13,"bodyClass":"","normalizeMath":false,"toc":[{"id":"what-mcp-is","label":"What MCP is"},{"id":"why-mcp-exists-the-problem-it-solves","label":"Why MCP Exists: The Problem It Solves"},{"id":"mcp-architecture-how-the-pieces-fit-together","label":"MCP Architecture: How the Pieces Fit Together"},{"id":"what-mcp-is-used-for","label":"What MCP is used for"},{"id":"why-this-pattern-matters-key-benefits","label":"Why This Pattern Matters: Key Benefits"},{"id":"mcp-components-the-3-primitives","label":"MCP components (the 3 primitives)"},{"id":"example-1-single-user-lookup-simple","label":"Example 1: Single User Lookup (Simple)"},{"id":"part-a-mcp-server-tools-resource-prompt","label":"Part A \u2014 MCP Server (Tools + Resource + Prompt)"},{"id":"part-b-mcp-client-langchain-llm-uses-prompt-resource-tools","label":"Part B \u2014 MCP Client + LangChain LLM (uses Prompt + Resource + Tools)"},{"id":"example-2-multi-tool-router-advanced","label":"Example 2: Multi-Tool Router (Advanced)"},{"id":"what-you-should-observe","label":"What you should observe"},{"id":"summary-why-mcp-matters","label":"Summary: Why MCP Matters"}],"html":"<div class=\\"container\\">\\n        \\n\\n        <div class=\\"tr-note\\">\\n            <strong>Where this fits</strong>\\n            This chapter is the beginner MCP introduction using a local\\n            database-style example. The complete technical treatment of MCP\\n            discovery, remote servers, authentication, token validation, and\\n            best practices lives in\\n            <a href=\\"/tutorials/part3-agent-protocols/02-mcp-discovery-remote-auth\\">Chapter 2</a>.\\n        </div>\\n\\n        <div class=\\"tr-update\\">\\n            <strong>Protocol version boundary</strong>\\n            Tools, resources, prompts, schemas, host policy, and the decorator\\n            examples remain the durable concepts. The current MCP\\n            <code>2026-07-28</code> wire protocol is stateless: each request\\n            carries version/capability metadata and the server implements\\n            <code>server/discover</code>; there is no mandatory\\n            <code>initialize</code> handshake or protocol session. High-level\\n            adapters may hide those messages or still expose a 2025\\n            compatibility API. Pin mutually compatible client, adapter, and\\n            server releases, and use <a href=\\"/tutorials/part3-agent-protocols/04-mcp-2025-update\\">Chapter\\n            4</a> for the exact current wire model.\\n        </div>\\n\\n        <div class=\\"section\\">\\n            <h2 id=\\"what-mcp-is\\">What MCP is</h2>\\n            <p>\\n                <strong>MCP (Model Context Protocol)</strong> is a standard way for an \\"AI host\\" (an app that uses an LLM) to connect to external capabilities through MCP servers.\\n            </p>\\n            <p>\\n                Instead of hard-coding integrations (DB, CRM, ticketing, etc.) inside every app, you run a server that publishes capabilities in a consistent shape. The host connects as an MCP client, discovers what the server offers, and then uses those capabilities to answer user questions (often with an LLM making decisions).\\n            </p>\\n            <div class=\\"highlight-box\\" style=\\"margin-top: 20px;\\">\\n                <strong>The Key Insight:</strong> MCP provides a unified framework so the agent doesn\'t need to learn every system\'s custom API\u2014it just talks MCP.\\n            </div>\\n        </div>\\n\\n        <hr class=\\"divider\\">\\n\\n        <div class=\\"section\\">\\n            <h2 id=\\"why-mcp-exists-the-problem-it-solves\\">Why MCP Exists: The Problem It Solves</h2>\\n            \\n            <h3 id=\\"without-mcp\\">Without MCP</h3>\\n            <p>Every connector looks different:</p>\\n            <ul>\\n                <li>Different endpoints, auth mechanisms, and payload shapes</li>\\n                <li>Agents must hardcode provider-specific logic</li>\\n                <li>Hard to secure and audit consistently</li>\\n                <li>Hard to swap systems (e.g., DB vendor changes) without changing agent logic</li>\\n            </ul>\\n\\n            <div class=\\"info-box\\">\\n                <h4>Example of the Problem:</h4>\\n                <p>Without MCP, if you want user data, you might need to know:</p>\\n                <ul style=\\"margin-top: 10px;\\">\\n                    <li>Is it <code class=\\"inline-code\\">GET https://api.vendor.com/users?email=...</code>?</li>\\n                    <li>Or <code class=\\"inline-code\\">SELECT user_id, email, plan FROM users WHERE email = :email</code>?</li>\\n                    <li>Or <code class=\\"inline-code\\">sdk.users.get(email)</code>?</li>\\n                </ul>\\n                <p style=\\"margin-top: 10px;\\">Each requires different code, different error handling, different security patterns.</p>\\n            </div>\\n\\n            <h3 id=\\"with-mcp-unified-abstraction\\">With MCP: Unified Abstraction</h3>\\n            <p>MCP standardizes the interface. Whether the tool internally:</p>\\n            <ul>\\n                <li>calls an HTTP API,</li>\\n                <li>runs a database query,</li>\\n                <li>invokes a SaaS SDK,</li>\\n                <li>reads from a file system,</li>\\n                <li>publishes to a message queue,</li>\\n            </ul>\\n            <p>The agent <em>always</em> does:</p>\\n            <div class=\\"command-box\\" style=\\"background: #f8f9fa; color: #2c3e50;\\">\\n                call_tool(\\"tool_name\\", {\\"arg\\": \\"value\\"})\\n            </div>\\n            \\n            <div class=\\"highlight-box\\" style=\\"margin-top: 20px;\\">\\n                <strong>One-Sentence Summary:</strong> MCP standardizes how agents discover safe context (resources), learn correct workflows (prompts), and execute controlled operations (tools), so underlying HTTP/DB/SaaS operations become consistent and auditable.\\n            </div>\\n        </div>\\n\\n        <hr class=\\"divider\\">\\n\\n        <div class=\\"section\\">\\n            <h2 id=\\"mcp-architecture-how-the-pieces-fit-together\\">MCP Architecture: How the Pieces Fit Together</h2>\\n            \\n            <div class=\\"info-box\\">\\n                <h4>Three Main Components:</h4>\\n                <div style=\\"margin-top: 15px;\\">\\n                    <p><strong>1. MCP Server</strong></p>\\n                    <ul style=\\"margin-left: 20px; margin-top: 5px;\\">\\n                        <li>Exposes Tools / Resources / Prompts</li>\\n                        <li>Enforces its own security policies</li>\\n                        <li>Hides implementation details (DB, HTTP, SDK)</li>\\n                    </ul>\\n                </div>\\n                <div style=\\"margin-top: 15px;\\">\\n                    <p><strong>2. MCP Client (your app)</strong></p>\\n                    <ul style=\\"margin-left: 20px; margin-top: 5px;\\">\\n                        <li>Connects to the server</li>\\n                        <li>Fetches prompts and resources</li>\\n                        <li>Calls tools</li>\\n                        <li>Feeds content to the LLM</li>\\n                    </ul>\\n                </div>\\n                <div style=\\"margin-top: 15px;\\">\\n                    <p><strong>3. LLM / Agent</strong></p>\\n                    <ul style=\\"margin-left: 20px; margin-top: 5px;\\">\\n                        <li>Reads the prompt + policy + schema</li>\\n                        <li>Decides which tool to call and with what arguments</li>\\n                        <li>Never directly touches the DB/API\u2014only through tools</li>\\n                    </ul>\\n                </div>\\n            </div>\\n\\n            <div class=\\"highlight-box\\" style=\\"margin-top: 20px;\\">\\n                <strong>Important:</strong> MCP is not \\"replacing HTTP.\\" MCP is a standard protocol on top of whatever the server uses internally. The MCP server might call HTTP APIs, databases, SDKs, etc., but the MCP client always speaks MCP.\\n            </div>\\n        </div>\\n\\n        <hr class=\\"divider\\">\\n\\n        <div class=\\"section\\">\\n            <h2 id=\\"what-mcp-is-used-for\\">What MCP is used for</h2>\\n            <p>MCP is used when you want an LLM-powered system to:</p>\\n            <ul>\\n                <li><strong>Discover what it can do</strong> (what tools exist, what resources exist, what prompts exist)</li>\\n                <li><strong>Invoke actions safely</strong> (call a tool to fetch data or perform operations)</li>\\n                <li><strong>Fetch reference context reliably</strong> (read policies/schemas/config as resources)</li>\\n                <li><strong>Reuse standard workflows</strong> (prompts that encode \\"how to do this safely\\")</li>\\n            </ul>\\n            <div class=\\"highlight-box\\">\\n                <strong>In short:</strong> MCP helps you build tool-using LLM apps without reinventing a connector interface for every integration.\\n            </div>\\n        </div>\\n\\n        <hr class=\\"divider\\">\\n\\n        <div class=\\"section\\">\\n            <h2 id=\\"why-this-pattern-matters-key-benefits\\">Why This Pattern Matters: Key Benefits</h2>\\n\\n            <h3 id=\\"1-separation-of-concerns-read-vs-write\\">1. Separation of Concerns: Read vs. Write</h3>\\n            <div class=\\"info-box\\">\\n                <p><strong>Resources</strong> are safe, cacheable \\"reference documents\\" for the agent.</p>\\n                <p style=\\"margin-top: 10px;\\"><strong>Tools</strong> are the only things that touch live data (DB/API), so you can lock them down and audit them.</p>\\n            </div>\\n            <p>This prevents the \\"LLM invents SQL\\" problem and makes governance easier.</p>\\n\\n            <h3 id=\\"2-reduced-coupling-and-increased-portability\\">2. Reduced Coupling and Increased Portability</h3>\\n            <p>You can replace the server implementation (DB \u2192 HTTP API \u2192 different vendor) without changing:</p>\\n            <ul>\\n                <li>the agent logic</li>\\n                <li>the client tool-calling logic</li>\\n            </ul>\\n            <p>...as long as the MCP tool contract remains stable.</p>\\n\\n            <h3 id=\\"3-improved-security-posture\\">3. Improved Security Posture</h3>\\n            <p>In enterprise setups, you want:</p>\\n            <ul>\\n                <li>Strict tool allowlists</li>\\n                <li>Input schemas and validation</li>\\n                <li>Auditing of tool calls</li>\\n                <li>Minimal exfiltration surface</li>\\n            </ul>\\n            <p>MCP naturally fits this because the LLM can\'t \\"reach into the DB\\" directly\u2014only through defined tools.</p>\\n\\n            <h3 id=\\"4-standardized-workflows\\">4. Standardized Workflows</h3>\\n            <p><strong>Prompts</strong> standardize agent behavior across many clients. They teach the agent the safe/recommended sequence of operations.</p>\\n        </div>\\n\\n        <hr class=\\"divider\\">\\n\\n        <div class=\\"section\\">\\n            <h2 id=\\"mcp-components-the-3-primitives\\">MCP components (the 3 primitives)</h2>\\n\\n            <h3 id=\\"1-tools-do-something\\">1) Tools = \\"do something\\"</h3>\\n            <p>A <strong>Tool</strong> is a callable function exposed by the server.</p>\\n            <ul>\\n                <li><strong>Input:</strong> arguments (e.g., user_id)</li>\\n                <li><strong>Output:</strong> structured data (e.g., dict/JSON)</li>\\n                <li><strong>Use for:</strong> database reads, API calls, computations, actions</li>\\n            </ul>\\n            <div class=\\"info-box\\">\\n                <h4>In this tutorial:</h4>\\n                <ul>\\n                    <li><code class=\\"inline-code\\">db_get_user_profile(user_id)</code></li>\\n                    <li><code class=\\"inline-code\\">db_get_subscription(user_id)</code></li>\\n                </ul>\\n            </div>\\n\\n            <h3 id=\\"2-resources-read-something\\">2) Resources = \\"read something\\"</h3>\\n            <p>A <strong>Resource</strong> is read-only content, addressed by a URI.</p>\\n            <ul>\\n                <li><strong>Input:</strong> a URI like <code class=\\"inline-code\\">db://tooling/guide</code></li>\\n                <li><strong>Output:</strong> text or JSON content</li>\\n                <li><strong>Use for:</strong> tool guides, schemas, policy text, reference docs</li>\\n            </ul>\\n            <div class=\\"info-box\\">\\n                <h4>In this tutorial:</h4>\\n                <ul>\\n                    <li><code class=\\"inline-code\\">db://tooling/guide</code> (instructions for when to call which tool)</li>\\n                </ul>\\n            </div>\\n\\n            <h3 id=\\"3-prompts-how-to-think-workflow-templates\\">3) Prompts = \\"how to think / workflow templates\\"</h3>\\n            <p>A <strong>Prompt</strong> is a server-provided template that returns structured messages (system/user) to feed to an LLM.</p>\\n            <ul>\\n                <li><strong>Input:</strong> parameters (e.g., question, user_id)</li>\\n                <li><strong>Output:</strong> \\"messages\\" that guide the LLM reliably</li>\\n            </ul>\\n            <div class=\\"info-box\\">\\n                <h4>In this tutorial:</h4>\\n                <ul>\\n                    <li><code class=\\"inline-code\\">account_assistant(question, user_id)</code> returns a workflow telling the LLM:\\n                        <ol class=\\"numbered-list\\" style=\\"margin-top: 10px;\\">\\n                            <li>read the guide resource,</li>\\n                            <li>choose the correct tool(s),</li>\\n                            <li>summarize results.</li>\\n                        </ol>\\n                    </li>\\n                </ul>\\n            </div>\\n        </div>\\n\\n        <hr class=\\"divider\\">\\n\\n        <div class=\\"section\\">\\n            <h2 id=\\"example-1-single-user-lookup-simple\\">Example 1: Single User Lookup (Simple)</h2>\\n            <div class=\\"highlight-box\\">\\n                <strong>User asks:</strong>\\n                <p style=\\"margin-top: 10px; font-style: italic;\\">\\"Confirm my name and what plan I\'m on.\\"</p>\\n            </div>\\n            \\n            <p><strong>The LLM should:</strong></p>\\n            <ul>\\n                <li>call <code class=\\"inline-code\\">db_get_user_profile(user_id)</code> for name/email</li>\\n                <li>call <code class=\\"inline-code\\">db_get_subscription(user_id)</code> for plan/renewal</li>\\n                <li>combine them into a single answer</li>\\n            </ul>\\n\\n            <p><strong>We\'ll expose:</strong></p>\\n            <ul>\\n                <li>2 tools (two \\"DB reads\\")</li>\\n                <li>1 resource (a read-only tool guide)</li>\\n                <li>1 prompt (a standard workflow template)</li>\\n            </ul>\\n        </div>\\n\\n        <hr class=\\"divider\\">\\n\\n        <div class=\\"section\\">\\n            <h2 id=\\"part-a-mcp-server-tools-resource-prompt\\">Part A \u2014 MCP Server (Tools + Resource + Prompt)</h2>\\n            <p><strong>Save as:</strong> <code class=\\"inline-code\\">mcp_db_server.py</code></p>\\n\\n            <div class=\\"code-block\\">\\n                <div class=\\"code-header\\">mcp_db_server.py</div>\\n                <pre><code class=\\"language-python\\"># pip install \\"mcp[cli]\\"\\n\\nfrom mcp.server.fastmcp import FastMCP\\nfrom mcp.server.fastmcp.prompts import base\\n\\n# This creates an MCP server instance.\\n# \\"json_response=True\\" means tool outputs can be structured JSON.\\nmcp = FastMCP(\\"DBMCP\\", stateless_http=True, json_response=True)\\n\\n\\n# ============================================================\\n# RESOURCE: read-only context\\n# ============================================================\\n# URI: db://tooling/guide\\n# The client reads this via session.read_resource(\\"db://tooling/guide\\")\\n#\\n# Think of this as \\"documentation the LLM can read\\":\\n# - what tools exist\\n# - when to use which tool\\n# - rules (like \\"user_id must come from host identity\\")\\n@mcp.resource(\\"db://tooling/guide\\")\\ndef tooling_guide() -&gt; str:\\n    # Returned value is just text (could also be JSON).\\n    # The MCP client will receive it as resource contents.\\n    return (\\n        \\"Tool guide:\\\\n\\"\\n        \\"- Use db_get_user_profile(user_id) for: name, email, profile.\\\\n\\"\\n        \\"- Use db_get_subscription(user_id) for: plan, billing, renew, payment.\\\\n\\\\n\\"\\n        \\"Rules:\\\\n\\"\\n        \\"- user_id must come from the host identity, not from user text.\\\\n\\"\\n        \\"- If question asks for both profile + plan, call BOTH tools.\\\\n\\"\\n    )\\n\\n\\n# ============================================================\\n# PROMPT: reusable workflow template\\n# ============================================================\\n# Name: account_assistant (the function name is the prompt name)\\n#\\n# The client calls this via session.get_prompt(\\"account_assistant\\", arguments={...})\\n# The server returns structured messages (system/user) suitable for an LLM.\\n#\\n# This is NOT a tool call. It does not read DB. It provides instructions.\\n@mcp.prompt(title=\\"Account assistant\\")\\ndef account_assistant(question: str, user_id: str) -&gt; list[base.Message]:\\n    return [\\n        base.SystemMessage(\\n            \\"You are an account assistant.\\\\n\\"\\n            \\"Workflow:\\\\n\\"\\n            \\"1) Read resource db://tooling/guide\\\\n\\"\\n            \\"2) Decide which tool(s) to call\\\\n\\"\\n            \\"3) Call the tool(s)\\\\n\\"\\n            \\"4) Summarize results briefly\\\\n\\"\\n        ),\\n        base.UserMessage(\\n            # This is the actual user task formatted in a consistent way.\\n            f\\"user_id={user_id}\\\\nquestion={question}\\"\\n        ),\\n    ]\\n\\n\\n# ============================================================\\n# TOOL 1: action (DB read) - profile\\n# ============================================================\\n# Tools are invoked by the client as: tools/call with name + arguments.\\n@mcp.tool()\\nasync def db_get_user_profile(user_id: str) -&gt; dict:\\n    # In real life: query your database.\\n    # Here: mocked data.\\n    return {\\n        \\"user_id\\": user_id,\\n        \\"full_name\\": \\"Alice Example\\",\\n        \\"email\\": \\"alice@bank.com\\",\\n    }\\n\\n\\n# ============================================================\\n# TOOL 2: action (DB read) - subscription\\n# ============================================================\\n@mcp.tool()\\nasync def db_get_subscription(user_id: str) -&gt; dict:\\n    # In real life: query your database.\\n    # Here: mocked data.\\n    return {\\n        \\"user_id\\": user_id,\\n        \\"plan\\": \\"Pro\\",\\n        \\"renews_at\\": \\"2026-01-10\\",\\n    }\\n\\n\\nif __name__ == \\"__main__\\":\\n    # Run the MCP server over Streamable HTTP (network server).\\n    # Your MCP client will connect to http://127.0.0.1:8765/mcp (default).\\n    mcp.run(transport=\\"streamable-http\\")</code></pre>\\n            </div>\\n\\n            <p><strong>Run it:</strong></p>\\n            <div class=\\"command-box\\">python mcp_db_server.py</div>\\n        </div>\\n\\n        <hr class=\\"divider\\">\\n\\n        <div class=\\"section\\">\\n            <h2 id=\\"part-b-mcp-client-langchain-llm-uses-prompt-resource-tools\\">Part B \u2014 MCP Client + LangChain LLM (uses Prompt + Resource + Tools)</h2>\\n            <p><strong>Save as:</strong> <code class=\\"inline-code\\">mcp_client_langchain.py</code></p>\\n\\n            <div class=\\"code-block\\">\\n                <div class=\\"code-header\\">mcp_client_langchain.py</div>\\n                <pre><code class=\\"language-python\\"># pip install langchain langchain-openai langchain-mcp-adapters mcp\\n# export OPENAI_API_KEY=\\"...\\"\\n# export OPENAI_MODEL=\\"a currently supported tool-capable model\\"\\n\\nimport asyncio\\nimport os\\nfrom langchain_openai import ChatOpenAI\\nfrom langchain_core.messages import SystemMessage\\n\\nfrom langchain_mcp_adapters.client import MultiServerMCPClient\\nfrom langchain_mcp_adapters.resources import load_mcp_resources\\nfrom langchain_mcp_adapters.prompts import load_mcp_prompt\\n\\nMCP_URL = \\"http://127.0.0.1:8765/mcp\\"\\n\\n# IMPORTANT: this is host-derived identity (from your auth system in real life).\\n# The user/LLM should not be allowed to choose it.\\nUSER_ID = \\"u_742\\"\\n\\nasync def main():\\n    # ------------------------------------------------------------\\n    # 1) Connect to MCP server\\n    # ------------------------------------------------------------\\n    mcp_client = MultiServerMCPClient({\\n        \\"db\\": {\\"transport\\": \\"http\\", \\"url\\": MCP_URL}\\n    })\\n\\n    # ------------------------------------------------------------\\n    # 2) Load server tools -&gt; LangChain tools\\n    # ------------------------------------------------------------\\n    # tools is a list of LangChain Tool wrappers.\\n    # Example:\\n    #   tools[0].name == \\"db_get_user_profile\\"\\n    #   tools[1].name == \\"db_get_subscription\\"\\n    tools = await mcp_client.get_tools()\\n\\n    # Create a tool-capable LLM and bind these tools so it can request tool calls.\\n    llm = ChatOpenAI(model=os.environ[\\"OPENAI_MODEL\\"], temperature=0).bind_tools(tools)\\n\\n    question = \\"Confirm my name and what plan I\'m on.\\"\\n\\n    # ------------------------------------------------------------\\n    # 3) Pull Resource + Prompt from MCP server\\n    # ------------------------------------------------------------\\n    async with mcp_client.session(\\"db\\") as session:\\n        # 3A) Read the Resource (guide/policy text)\\n        # blobs is a list of Blob objects returned by the adapter.\\n        # Since we ask for 1 URI, blobs typically contains exactly 1 element.\\n        blobs = await load_mcp_resources(session, uris=[\\"db://tooling/guide\\"])\\n\\n        # guide_text is a plain string extracted from the Blob:\\n        # example:\\n        # \\"Tool guide:\\\\n- Use db_get_user_profile(user_id) for: ...\\\\n...\\"\\n        guide_text = blobs[0].as_string() if blobs else \\"\\"\\n\\n        # 3B) Get the Prompt (server-defined messages for the LLM)\\n        # prompt_msgs is a list of LangChain message objects.\\n        # typically something like:\\n        #   [SystemMessage(\\"...workflow...\\"), HumanMessage(\\"user_id=... question=...\\")]\\n        prompt_msgs = await load_mcp_prompt(\\n            session,\\n            \\"account_assistant\\",\\n            arguments={\\"question\\": question, \\"user_id\\": USER_ID}\\n        )\\n\\n    # ------------------------------------------------------------\\n    # 4) Build the messages we send to the LLM\\n    # ------------------------------------------------------------\\n    messages = []\\n\\n    # Add the resource guide as system context.\\n    # This lets the LLM learn \\"which tool to use for which question\\".\\n    if guide_text.strip():\\n        messages.append(SystemMessage(content=\\"(MCP Resource) Tool guide:\\\\n\\" + guide_text))\\n\\n    # Add the server-defined prompt messages (workflow template).\\n    messages.extend(prompt_msgs)\\n\\n    # ------------------------------------------------------------\\n    # 5) Agent loop: ask LLM, run tool calls, feed results back\\n    # ------------------------------------------------------------\\n    while True:\\n        # Ask the LLM for the next step\\n        ai_msg = await llm.ainvoke(messages)\\n        messages.append(ai_msg)\\n\\n        # If the LLM requests tool calls, they appear here.\\n        # Example tool_calls:\\n        # [\\n        #   {\\"name\\":\\"db_get_user_profile\\",\\"args\\":{\\"user_id\\":\\"u_742\\"}},\\n        #   {\\"name\\":\\"db_get_subscription\\",\\"args\\":{\\"user_id\\":\\"u_742\\"}}\\n        # ]\\n        tool_calls = getattr(ai_msg, \\"tool_calls\\", None)\\n\\n        # If no tool calls, the model produced a final natural-language answer.\\n        if not tool_calls:\\n            print(\\"\\\\nFINAL ANSWER:\\")\\n            print(ai_msg.content)\\n            break\\n\\n        # Execute each tool call the model requested\\n        for tc in tool_calls:\\n            tool_name = tc[\\"name\\"]   # string: which tool to run\\n            tool_args = tc[\\"args\\"]   # dict: arguments for that tool\\n\\n            # SAFETY: force user_id from host, not from the model.\\n            # Even if the model tried to pass a different user_id, we override it.\\n            if \\"user_id\\" in tool_args:\\n                tool_args[\\"user_id\\"] = USER_ID\\n\\n            # Find the tool object by name\\n            tool = next(t for t in tools if t.name == tool_name)\\n\\n            # Run the tool. tool_result is usually a dict returned by the MCP tool.\\n            # Example:\\n            # {\\"user_id\\":\\"u_742\\",\\"full_name\\":\\"Alice Example\\",\\"email\\":\\"alice@bank.com\\"}\\n            tool_result = await tool.ainvoke(tool_args)\\n\\n            # Feed tool output back to the LLM as system context.\\n            messages.append(SystemMessage(content=f\\"(Tool result) {tool_name}: {tool_result}\\"))\\n\\nif __name__ == \\"__main__\\":\\n    asyncio.run(main())</code></pre>\\n            </div>\\n\\n            <p><strong>Run it:</strong></p>\\n            <div class=\\"command-box\\">python mcp_client_langchain.py</div>\\n        </div>\\n\\n        <hr class=\\"divider\\">\\n\\n        <div class=\\"section\\">\\n            <h2 id=\\"example-2-multi-tool-router-advanced\\">Example 2: Multi-Tool Router (Advanced)</h2>\\n            <p>This example demonstrates the power of MCP\'s unified framework with:</p>\\n            <ul>\\n                <li><strong>2 tools:</strong> profile lookup and orders lookup</li>\\n                <li><strong>2 prompts:</strong> workflow for each tool</li>\\n                <li><strong>3 resources:</strong> shared policy and separate schemas</li>\\n                <li><strong>LLM routing:</strong> agent chooses which tool to call based on the question</li>\\n            </ul>\\n\\n            <h3 id=\\"server-code-multiple-tools-resources-prompts\\">Server Code (Multiple Tools + Resources + Prompts)</h3>\\n            <div class=\\"code-block\\">\\n                <div class=\\"code-header\\">mcp_server_advanced.py</div>\\n                <pre><code class=\\"language-python\\"># filepath: examples/mcp_server_advanced.py\\n# pip install \\"mcp[cli]\\"\\n\\nfrom mcp.server.fastmcp import FastMCP\\n\\nmcp = FastMCP(\\"Bank-DB-MCP\\", stateless_http=True, json_response=True)\\n\\n# -------------------------\\n# RESOURCES (read-only)\\n# -------------------------\\n\\n@mcp.resource(\\"db://policy/access\\")\\ndef policy_access() -&gt; str:\\n    return (\\n        \\"POLICY:\\\\n\\"\\n        \\"- Only allow lookups by email (no bulk export).\\\\n\\"\\n        \\"- Return only permitted fields.\\\\n\\"\\n        \\"- If request is ambiguous, ask a clarifying question.\\\\n\\"\\n    )\\n\\n@mcp.resource(\\"db://schema/user_profile\\")\\ndef schema_user_profile() -&gt; str:\\n    return (\\n        \\"SCHEMA user_profile:\\\\n\\"\\n        \\"- email: string (unique)\\\\n\\"\\n        \\"- full_name: string\\\\n\\"\\n        \\"- tier: enum(silver|gold|platinum)\\\\n\\"\\n        \\"- status: enum(active|suspended)\\\\n\\"\\n        \\"Permitted output fields: email, full_name, tier, status\\\\n\\"\\n    )\\n\\n@mcp.resource(\\"db://schema/user_orders\\")\\ndef schema_user_orders() -&gt; str:\\n    return (\\n        \\"SCHEMA user_orders:\\\\n\\"\\n        \\"- email: string\\\\n\\"\\n        \\"- orders: list of { order_id: string, total: number, state: string }\\\\n\\"\\n        \\"Permitted output fields: email, orders\\\\n\\"\\n    )\\n\\n# -------------------------\\n# PROMPTS (server workflows)\\n# -------------------------\\n\\n@mcp.prompt()\\ndef workflow_user_profile() -&gt; str:\\n    return (\\n        \\"WORKFLOW: User Profile Lookup\\\\n\\"\\n        \\"1) Read db://policy/access\\\\n\\"\\n        \\"2) Read db://schema/user_profile\\\\n\\"\\n        \\"3) Call tool db_get_user_profile with {\\\\\\"email\\\\\\": \\\\\\"...\\\\\\"}\\\\n\\"\\n        \\"4) Return ONLY permitted fields.\\\\n\\"\\n    )\\n\\n@mcp.prompt()\\ndef workflow_user_orders() -&gt; str:\\n    return (\\n        \\"WORKFLOW: User Orders Lookup\\\\n\\"\\n        \\"1) Read db://policy/access\\\\n\\"\\n        \\"2) Read db://schema/user_orders\\\\n\\"\\n        \\"3) Call tool db_get_user_orders with {\\\\\\"email\\\\\\": \\\\\\"...\\\\\\"}\\\\n\\"\\n        \\"4) Return ONLY permitted fields.\\\\n\\"\\n    )\\n\\n# -------------------------\\n# TOOLS (actions)\\n# -------------------------\\n\\n@mcp.tool()\\ndef db_get_user_profile(email: str) -&gt; dict:\\n    # Unified interface: whether this internally calls HTTP, SQL, or SDK,\\n    # the client always uses: call_tool(\\"db_get_user_profile\\", {\\"email\\": \\"...\\"})\\n    fake_profiles = {\\n        \\"alice@bank.com\\": {\\n            \\"email\\": \\"alice@bank.com\\",\\n            \\"full_name\\": \\"Alice Chen\\",\\n            \\"tier\\": \\"gold\\",\\n            \\"status\\": \\"active\\"\\n        },\\n        \\"bob@bank.com\\": {\\n            \\"email\\": \\"bob@bank.com\\",\\n            \\"full_name\\": \\"Bob Singh\\",\\n            \\"tier\\": \\"silver\\",\\n            \\"status\\": \\"suspended\\"\\n        },\\n    }\\n    return fake_profiles.get(email) or {\\"error\\": \\"not_found\\"}\\n\\n@mcp.tool()\\ndef db_get_user_orders(email: str) -&gt; dict:\\n    fake_orders = {\\n        \\"alice@bank.com\\": {\\n            \\"email\\": \\"alice@bank.com\\",\\n            \\"orders\\": [\\n                {\\"order_id\\": \\"A1001\\", \\"total\\": 129.50, \\"state\\": \\"PAID\\"},\\n                {\\"order_id\\": \\"A1002\\", \\"total\\": 58.00, \\"state\\": \\"REFUNDED\\"},\\n            ],\\n        }\\n    }\\n    return fake_orders.get(email) or {\\"error\\": \\"not_found\\"}\\n\\nif __name__ == \\"__main__\\":\\n    mcp.run(transport=\\"streamable-http\\")</code></pre>\\n            </div>\\n\\n            <h3 id=\\"client-code-llm-router-multiple-resources\\">Client Code (LLM Router + Multiple Resources)</h3>\\n            <div class=\\"code-block\\">\\n                <div class=\\"code-header\\">mcp_client_advanced.py</div>\\n                <pre><code class=\\"language-python\\"># filepath: examples/mcp_client_advanced.py\\n# pip install mcp\\n\\nimport asyncio\\nimport json\\nimport re\\nfrom typing import Any, Dict, Literal, TypedDict\\n\\nfrom mcp import ClientSession\\nfrom mcp.client.streamable_http import streamable_http_client\\n\\nMCP_URL = \\"http://localhost:8000/mcp\\"\\n\\n\\nclass ToolDecision(TypedDict):\\n    tool_name: Literal[\\"db_get_user_profile\\", \\"db_get_user_orders\\"]\\n    arguments: Dict[str, Any]\\n    prompt_to_use: Literal[\\"workflow_user_profile\\", \\"workflow_user_orders\\"]\\n\\n\\ndef extract_email(text: str) -&gt; str | None:\\n    m = re.search(r\\"[\\\\w\\\\.-]+@[\\\\w\\\\.-]+\\\\.\\\\w+\\", text)\\n    return m.group(0) if m else None\\n\\n\\ndef llm_choose_tool(\\n    user_question: str,\\n    workflow_profile: str,\\n    workflow_orders: str,\\n    policy_text: str,\\n    schema_profile: str,\\n    schema_orders: str,\\n) -&gt; ToolDecision:\\n    \\"\\"\\"\\n    This simulates what GPT would do:\\n    - reads workflows + policy + schemas\\n    - picks the right tool\\n    - returns a structured decision\\n\\n    In production, replace this with a real LLM call that outputs JSON.\\n    \\"\\"\\"\\n    email = extract_email(user_question) or \\"alice@bank.com\\"\\n\\n    # Minimal routing logic (standing in for LLM reasoning)\\n    if \\"order\\" in user_question.lower() or \\"purchase\\" in user_question.lower():\\n        return {\\n            \\"tool_name\\": \\"db_get_user_orders\\",\\n            \\"arguments\\": {\\"email\\": email},\\n            \\"prompt_to_use\\": \\"workflow_user_orders\\"\\n        }\\n    else:\\n        return {\\n            \\"tool_name\\": \\"db_get_user_profile\\",\\n            \\"arguments\\": {\\"email\\": email},\\n            \\"prompt_to_use\\": \\"workflow_user_profile\\"\\n        }\\n\\n\\nasync def main():\\n    user_question = \\"Show me the orders for alice@bank.com\\"\\n\\n    async with streamable_http_client(MCP_URL) as (read, write, _):\\n        async with ClientSession(read, write) as session:\\n            await session.initialize()\\n\\n            # 1) Discover server-provided workflows (prompts)\\n            p_profile = await session.get_prompt(\\"workflow_user_profile\\")\\n            p_orders = await session.get_prompt(\\"workflow_user_orders\\")\\n\\n            workflow_profile = json.dumps(p_profile, indent=2, default=str)\\n            workflow_orders = json.dumps(p_orders, indent=2, default=str)\\n\\n            # 2) Read shared policy + schemas (resources)\\n            r_policy = await session.read_resource(\\"db://policy/access\\")\\n            r_schema_profile = await session.read_resource(\\"db://schema/user_profile\\")\\n            r_schema_orders = await session.read_resource(\\"db://schema/user_orders\\")\\n\\n            policy_text = json.dumps(r_policy, indent=2, default=str)\\n            schema_profile = json.dumps(r_schema_profile, indent=2, default=str)\\n            schema_orders = json.dumps(r_schema_orders, indent=2, default=str)\\n\\n            # 3) LLM chooses which tool to call\\n            decision = llm_choose_tool(\\n                user_question=user_question,\\n                workflow_profile=workflow_profile,\\n                workflow_orders=workflow_orders,\\n                policy_text=policy_text,\\n                schema_profile=schema_profile,\\n                schema_orders=schema_orders,\\n            )\\n\\n            print(\\"\\\\n--- TOOL DECISION (what GPT would output) ---\\")\\n            print(json.dumps(decision, indent=2))\\n\\n            # 4) Client executes the chosen tool via MCP\\n            tool_name = decision[\\"tool_name\\"]\\n            args = decision[\\"arguments\\"]\\n\\n            result = await session.call_tool(tool_name, arguments=args)\\n\\n            print(\\"\\\\n--- TOOL RESULT (from MCP server) ---\\")\\n            print(result.structuredContent or {\\"content\\": result.content})\\n\\n\\nif __name__ == \\"__main__\\":\\n    asyncio.run(main())</code></pre>\\n            </div>\\n\\n            <div class=\\"expected-output\\">\\n                <h4>Expected Output:</h4>\\n                <pre style=\\"background: white; padding: 10px; border-radius: 4px;\\"><code>--- TOOL DECISION (what GPT would output) ---\\n{\\n  \\"tool_name\\": \\"db_get_user_orders\\",\\n  \\"arguments\\": {\\n    \\"email\\": \\"alice@bank.com\\"\\n  },\\n  \\"prompt_to_use\\": \\"workflow_user_orders\\"\\n}\\n\\n--- TOOL RESULT (from MCP server) ---\\n{\\n  \\"email\\": \\"alice@bank.com\\",\\n  \\"orders\\": [\\n    {\\"order_id\\": \\"A1001\\", \\"total\\": 129.5, \\"state\\": \\"PAID\\"},\\n    {\\"order_id\\": \\"A1002\\", \\"total\\": 58.0, \\"state\\": \\"REFUNDED\\"}\\n  ]\\n}</code></pre>\\n            </div>\\n\\n            <div class=\\"info-box\\" style=\\"margin-top: 20px;\\">\\n                <h4>Key Takeaway from Example 2:</h4>\\n                <p>Even if <code class=\\"inline-code\\">db_get_user_profile</code> internally becomes <code class=\\"inline-code\\">GET https://internal-api/profile?email=...</code>, the client still calls it as <code class=\\"inline-code\\">call_tool(\\"db_get_user_profile\\", {\\"email\\": ...})</code></p>\\n                <p style=\\"margin-top: 10px;\\"><strong>That\'s the unified abstraction MCP provides.</strong></p>\\n            </div>\\n        </div>\\n\\n        <hr class=\\"divider\\">\\n\\n        <div class=\\"section\\">\\n            <h2 id=\\"what-you-should-observe\\">What you should observe</h2>\\n            <p>When you run the client:</p>\\n            <ul>\\n                <li>The LLM reads the <strong>resource</strong> (tool guide) and sees that:\\n                    <ul style=\\"margin-top: 8px;\\">\\n                        <li>name/email \u2192 <code class=\\"inline-code\\">db_get_user_profile</code></li>\\n                        <li>plan/renew \u2192 <code class=\\"inline-code\\">db_get_subscription</code></li>\\n                    </ul>\\n                </li>\\n                <li>The LLM reads the <strong>prompt</strong> (workflow) which tells it to:\\n                    <ul style=\\"margin-top: 8px;\\">\\n                        <li>read the guide, call tools, summarize</li>\\n                    </ul>\\n                </li>\\n                <li>The LLM will typically call both tools for the combined question.</li>\\n                <li>You\'ll see a final answer like:</li>\\n            </ul>\\n\\n            <div class=\\"expected-output\\">\\n                <h4>Expected Output:</h4>\\n                <p style=\\"font-style: italic; color: #2d3748;\\">\\n                    \\"Your name is Alice Example and your email is alice@bank.com. Your plan is Pro and it renews on 2026-01-10.\\"\\n                </p>\\n            </div>\\n        </div>\\n\\n        <hr class=\\"divider\\">\\n\\n        <div class=\\"section\\">\\n            <h2 id=\\"summary-why-mcp-matters\\">Summary: Why MCP Matters</h2>\\n            \\n            <ol class=\\"numbered-list\\">\\n                <li><strong>MCP gives a unified \\"capabilities interface\\"</strong>\\n                    <p style=\\"margin-top: 8px;\\">To the agent/client, tools look like callable functions, resources look like URIs you can read, and prompts look like workflow templates\u2014regardless of the underlying implementation.</p>\\n                </li>\\n                \\n                <li><strong>MCP separates \\"read-only context\\" from \\"actions\\"</strong>\\n                    <p style=\\"margin-top: 8px;\\">This is a big safety and design win. Resources are safe, audit-friendly, and cacheable. Tools are gated, validated, and permissioned.</p>\\n                </li>\\n                \\n                <li><strong>MCP reduces coupling and increases portability</strong>\\n                    <p style=\\"margin-top: 8px;\\">You can replace the server implementation without changing the agent logic or client tool-calling logic, as long as the MCP tool contract remains stable.</p>\\n                </li>\\n                \\n                <li><strong>MCP improves security posture</strong>\\n                    <p style=\\"margin-top: 8px;\\">The LLM can\'t \\"reach into the DB\\" directly\u2014only through defined, auditable tools with strict allowlists and input schemas.</p>\\n                </li>\\n            </ol>\\n\\n            <div class=\\"highlight-box\\" style=\\"margin-top: 30px;\\">\\n                <p><strong>Integration exercise:</strong> Run the relevant\\n                <code>list_*</code> operations against a real MCP server,\\n                replace the example tool/resource/prompt names with the\\n                discovered contracts, and add one test for each capability\\n                before enabling it for a model.</p>\\n            </div>\\n\\n            <p><strong>Official references:</strong>\\n                <a href=\\"https://modelcontextprotocol.io/specification/2026-07-28\\">MCP 2026-07-28 specification</a> \xb7\\n                <a href=\\"https://modelcontextprotocol.io/specification/2026-07-28/changelog\\">MCP key changes</a> \xb7\\n                <a href=\\"https://docs.langchain.com/oss/python/langchain/mcp\\">LangChain MCP adapters</a>\\n            </p>\\n        </div>\\n    </div>"}'),l={title:"MCP Fundamentals with a Simple Database Example",slug:"/part3-agent-protocols/01-mcp-fundamentals",description:'MCP (Model Context Protocol) is a standard way for an "AI host" (an app that uses an LLM) to connect to external capabilities through MCP servers.',sidebar_label:"1. MCP fundamentals",pagination_label:"1. MCP fundamentals",hide_title:!0,hide_table_of_contents:!0},c=void 0,d={},p=[];function u(e){return(0,o.jsx)(i.A,{content:a})}function m(e={}){const{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(u,{...e})}):u()}}}]);